using MyDrive;
using System.Text.Json;
if(args.Length!=1)throw new ArgumentException("Expected a scratch directory");
string root=Path.Combine(args[0],Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
var checks=new List<string>();void Check(bool condition,string name){if(!condition)throw new Exception(name);checks.Add(name);}
var migrated=JsonSerializer.Deserialize<Preferences>("{\"Theme\":\"Dark\",\"SyncthingConfigPath\":\"keep-existing\"}")!;
Check(migrated.BlipAutoOpenLinks&&migrated.BlipAutoConnectDesktop&&migrated.SyncthingConfigPath=="keep-existing","older preferences enable desktop watching and browser opening without losing sync settings");
var optedOut=JsonSerializer.Deserialize<Preferences>("{\"BlipAutoOpenLinks\":false,\"BlipAutoConnectDesktop\":false}")!;
Check(!optedOut.BlipAutoOpenLinks&&!optedOut.BlipAutoConnectDesktop,"saved browser and desktop-connection opt-outs survive reload");
string file=Path.Combine(root,"Received link.url");await File.WriteAllTextAsync(file,"[InternetShortcut]\r\nURL=https://example.com/?test=blip&literal=a%3Bb\r\nIconFile=ignored.exe");
var browser=new List<string>();string ledger=Path.Combine(root,"opened-links.json");
var opener=new BlipLinkOpener(ledger,url=>{browser.Add(url.AbsoluteUri);return Task.CompletedTask;});
var status=new BlipStatus{Authenticated=true,UserId=Guid.NewGuid().ToString(),DeviceId=Guid.NewGuid().ToString()};
BlipTransfer Transfer(string state="Completed",string direction="Incoming",string? path=null)=>new(){Id=Guid.NewGuid().ToString(),Status=state,Completed=state=="Completed",Direction=direction,LinkFiles=new(){path??file}};
var old=Transfer();await opener.ProcessAsync(status,new[]{old},true,candidate=>true);Check(browser.Count==0,"initial attachment skips old transfer history");
var pending=Transfer("Pending");await opener.ProcessAsync(status,new[]{old,pending},true,candidate=>true);Check(browser.Count==0,"pending links never open before completion");
pending.Status="Completed";pending.Completed=true;await opener.ProcessAsync(status,new[]{old,pending},true,candidate=>true);Check(browser.Count==1&&browser[0].StartsWith("https://example.com/"),"new completed incoming URL launches the browser callback");
await Task.WhenAll(Enumerable.Range(0,5).Select(_=>opener.ProcessAsync(status,new[]{old,pending},true,candidate=>true)));Check(browser.Count==1,"concurrent repeated snapshots open a link once");
var next=Transfer();await opener.ProcessAsync(status,new[]{old,pending,next},true,candidate=>true);Check(browser.Count==2,"a deliberate new transfer of the same URL can open again");
var outgoing=Transfer(direction:"Outgoing");var error=Transfer();error.HasError=true;var mismatch=Transfer();mismatch.Completed=false;
await opener.ProcessAsync(status,new[]{outgoing,error,mismatch},true,candidate=>true);Check(browser.Count==2,"outgoing errors and inconsistent completion never launch");
var disabled=Transfer();await opener.ProcessAsync(status,new[]{disabled},false,candidate=>true);await opener.ProcessAsync(status,new[]{disabled},true,candidate=>true);Check(browser.Count==2,"disabled transfers do not replay when enabled");
var restarted=new BlipLinkOpener(ledger,url=>{browser.Add(url.AbsoluteUri);return Task.CompletedTask;});
await restarted.ProcessAsync(status,Array.Empty<BlipTransfer>(),true,candidate=>true);await restarted.ProcessAsync(status,new[]{pending},true,candidate=>true);Check(browser.Count==2,"persisted claims prevent replay after restart even when history returns late");
Check(!File.ReadAllText(ledger).Contains("example.com")&&!File.ReadAllText(ledger).Contains(pending.Id),"ledger stores hashes without URLs or transfer identifiers");
string late=Path.Combine(root,"late.url");var waiting=Transfer(path:late);await opener.ProcessAsync(status,new[]{waiting},true,candidate=>true);await File.WriteAllTextAsync(late,"[InternetShortcut]\nURL=https://example.org/late");await opener.ProcessAsync(status,new[]{waiting},true,candidate=>true);Check(browser.Count==3,"a completed transfer waits for its shortcut file to become readable");
var invalid=new[]{"file:///C:/Windows/notepad.exe","javascript:alert(1)","ms-settings:privacy","https://user:password@example.com/","https://example.com/\\bad"};
foreach(string url in invalid){await File.WriteAllTextAsync(late,"[InternetShortcut]\nURL="+url);Check(await BlipLinkOpener.ReadShortcutAsync(late)==null,"rejects "+url.Split(':')[0]+" or malformed target");}
await File.WriteAllTextAsync(late,"[Other]\nURL=https://example.com/");Check(await BlipLinkOpener.ReadShortcutAsync(late)==null,"only the InternetShortcut URL field is used");
await File.WriteAllTextAsync(late,"[InternetShortcut]\nURL=https://example.com/\nURL=https://example.org/");Check(await BlipLinkOpener.ReadShortcutAsync(late)==null,"ambiguous shortcut targets are rejected");
string webloc=Path.Combine(root,"Mac.webloc");await File.WriteAllTextAsync(webloc,"<?xml version=\"1.0\"?><!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\"><plist version=\"1.0\"><dict><key>URL</key><string>https://example.net/mac?a=1&amp;b=2</string></dict></plist>");
Check((await BlipLinkOpener.ReadShortcutAsync(webloc))?.Host=="example.net","Apple web locations parse without fetching their DTD");
Check(await BlipLinkOpener.ReadShortcutAsync(@"\\server\share\link.url")==null,"network shortcut paths are not read");
int attempts=0;var failure=new BlipLinkOpener(Path.Combine(root,"failed.json"),_=>{attempts++;throw new IOException("fixture");});
await failure.ProcessAsync(status,Array.Empty<BlipTransfer>(),true,candidate=>true);await failure.ProcessAsync(status,new[]{next},true,candidate=>true);Check(failure.LastError.Length>0,"browser failure is visible");await failure.ProcessAsync(status,new[]{next},true,candidate=>true);Check(attempts==1,"failed browser dispatch does not loop");
var unapproved=Transfer();int deniedOpens=0;
var deny=new BlipLinkOpener(Path.Combine(root,"deny.json"),_=>{deniedOpens++;return Task.CompletedTask;});
await deny.ProcessAsync(status,Array.Empty<BlipTransfer>(),true);
await deny.ProcessAsync(status,new[]{unapproved},true);
await deny.ProcessAsync(status,new[]{unapproved},true,candidate=>true);
Check(deniedOpens==0,"missing sender policy denies opening and later approval never replays old links");
Console.WriteLine(JsonSerializer.Serialize(new{ok=true,checks},new JsonSerializerOptions{WriteIndented=true}));
